//! Synthetic compatibility fixtures generated by the retained Rust schema.
use harness_doc::{SessionCommandEntry, SessionDoc, SessionMessageEntry};
use loro::ExportMode;
use serde_json::json;
use std::path::Path;
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let dir = std::env::args()
        .nth(1)
        .ok_or("fixture output directory required")?;
    let dir = Path::new(&dir);
    std::fs::create_dir_all(dir)?;
    let doc = SessionDoc::init("synthetic-loro-fixture")?;
    for i in 0..130 {
        let entry: SessionMessageEntry = serde_json::from_value(json!({
            "id":format!("rust-{i}"), "role":"user", "deviceId":"synthetic-rust", "createdAt":1000+i,
            "status":"complete", "parts":[{"id":format!("p-{i}"),"kind":"text","text":format!("retained message {i} 🦀 é") }]
        }))?;
        doc.push_message(&entry)?;
    }
    let last: SessionMessageEntry = serde_json::from_value(json!({
        "id":"rust-assistant","role":"assistant","deviceId":"synthetic-rust","createdAt":1200,"status":"streaming",
        "parts":[{"id":"reason","kind":"reasoning","text":"thought 🦀"},{"id":"tool","kind":"tool","call":{"kind":"exec","command":"echo synthetic"},"resolved":true,"output":"synthetic"},{"id":"text","kind":"text","text":"answer"}]
    }))?;
    doc.push_message(&last)?;
    doc.push_queued(&serde_json::from_value(json!({"id":"q-rust","text":"queued before","issuedBy":"synthetic-rust","issuedAt":1200,"holdForTurnEnd":true}))?)?;
    let command: SessionCommandEntry = serde_json::from_value(
        json!({"id":"command-rust","payload":{"kind":"interrupt"},"issuedBy":"synthetic-rust","issuedAt":1200,"expiresAt":9999999999999_i64,"basedOn":{"turnId":"turn-synthetic","frontier":"synthetic"},"status":"pending"}),
    )?;
    doc.queue_command(&command)?;
    std::fs::write(dir.join("loro-baseline.bin"), doc.export_snapshot()?)?;
    let vv = doc.doc().oplog_vv();
    std::fs::write(dir.join("loro-baseline-vv.bin"), vv.encode())?;
    let mut writer = harness_doc::SegmentWriter::resume(&doc, 130, last.parts.clone());
    let mut parts = last.parts;
    if let harness_doc::MessagePart::Text { text, .. } = &mut parts[2] {
        text.push_str(" grows 🚀");
    }
    writer.sync(&parts)?;
    doc.set_message_status("rust-assistant", harness_doc::MessageStatus::Complete)?;
    doc.set_queued_text("q-rust", "edited offline by Rust", 1400)?;
    doc.set_command_status(
        "command-rust",
        harness_doc::SessionCommandStatus::Applied,
        Some("retained outcome"),
    )?;
    std::fs::write(
        dir.join("loro-incremental.bin"),
        doc.doc().export(ExportMode::updates(&vv))?,
    )?;
    std::fs::write(dir.join("loro-final-vv.bin"), doc.doc().oplog_vv().encode())?;
    std::fs::write(
        dir.join("loro-final.json"),
        serde_json::to_vec_pretty(
            &json!({"messages":doc.read_entries()?,"queue":doc.read_queue()?,"commands":doc.read_commands()?}),
        )?,
    )?;
    println!(
        "generated retained Rust Loro fixture: 131 messages, typed text/reasoning/tool, queue, command, incremental update and binary VVs"
    );
    Ok(())
}
